'use strict';
const routeState={hash:'',positions:new Map(),sheetFrames:new Map(),sheetId:0};
let currentSheet=null,toastTimer=0,lastFocus=null;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800);}
function animateContent(el){if(!el||reduced())return;el.getAnimations().forEach(a=>a.cancel());el.animate([{opacity:.75,transform:'translateY(4px)'},{opacity:1,transform:'none'}],{duration:160,easing:'cubic-bezier(.2,0,0,1)'});}
function currentHash(){return state.view==='day'?'day-'+state.day:state.view==='map'?(mapFilter==='all'?'map':'map-'+mapFilter):state.view;}
function parseRoute(){const h=location.hash.slice(1),day=h.match(/^day-(\d+)$/),mp=h.match(/^map(?:-(\d+))?$/);if(day){state.day=Math.min(18,Math.max(1,+day[1]));state.view='day';}else if(mp){mapFilter=mp[1]&&+mp[1]>=1&&+mp[1]<=18?mp[1]:'all';state.view='map';}else state.view=['itinerary','toolbox'].includes(h)?h:({overview:'itinerary',orders:'toolbox',memo:'toolbox'})[h]||'home';if(state.view==='home'){const t=tripToday(new Date(),DATA.days,tripCalendarChanges);if(t.inTrip)state.day=t.day;}}
function contextSnapshot(){return {view:state.view,day:state.day,hash:routeState.hash,y:scrollY,search:browseSearch,country:browseCountry,toolCategory,toolDay,mapFilter,mapContext:saveMapContext(),mapOrigin:mapSource};}
function restoreContext(c){if(!c)return;if(c.day)state.day=c.day;browseSearch=c.search??browseSearch;browseCountry=c.country??browseCountry;toolCategory=c.toolCategory??toolCategory;toolDay=c.toolDay??toolDay;mapFilter=c.mapFilter??mapFilter;if(c.mapContext)mapContexts.set(String(c.mapFilter),c.mapContext);mapSource=c.mapOrigin??mapSource;}
function saveScroll(){const c=contextSnapshot();routeState.positions.set(routeState.hash,c);history.replaceState({...history.state,route:routeState.hash,context:c},'',location.href);}
function persistUI(){state.browseCountry=browseCountry;state.browseSearch=browseSearch;state.toolCategory=toolCategory;state.toolDay=toolDay;persist();saveScroll();}
function navigate(view,day,options={}){const hadSheet=!!currentSheet;if(hadSheet)hideDrawer();else saveScroll();const previous=contextSnapshot();if(previous.view==='map'&&view!=='map')disposeMap();if(day!==undefined)state.day=Math.min(18,Math.max(1,+day));state.view=view==='today'?'home':view;if(state.view==='map'&&previous.view!=='map')mapSource={...previous,focusStep:options.originStep};if(options.context)restoreContext(options.context);const hash=currentHash(),existing=routeState.positions.get(hash);if(existing&&options.restore!==false&&!options.context)restoreContext(existing);if(state.view==='map'&&options.mapFilter!==undefined)mapFilter=String(options.mapFilter);const target=currentHash();if(!hadSheet&&!options.replace&&location.hash!=='#'+target)history.pushState({route:target},'','#'+target);else history.replaceState({route:target},'','#'+target);render({restoreY:options.context?.y??(options.scroll===false?scrollY:existing?.y??0)});if(options.mapKey)selectPendingMap(options.mapKey,options.originStep);if(options.focusStep!==undefined)focusStep(options.focusStep);saveScroll();}
function focusStep(index){requestAnimationFrame(()=>{const el=$('#step-'+index);if(!el)return;el.tabIndex=-1;el.scrollIntoView({block:'start',behavior:'instant'});el.focus({preventScroll:true});});}
function render({restoreY=0}={}){if(state.view!=='map')disposeMap();if(state.view==='home'){const t=tripToday(new Date(),DATA.days,tripCalendarChanges);if(t.inTrip)state.day=t.day;}const views={home,day:()=>dayView(false),itinerary:itineraryView,map:mapPage,toolbox:toolboxView};$('#page').innerHTML=(views[state.view]||home)();document.body.dataset.view=state.view==='home'&&tripToday(new Date(),DATA.days,tripCalendarChanges).inTrip?'today':state.view;routeState.hash=currentHash();document.title=journalTitle;renderRail();renderNav();updateClocks();if(state.view==='map')initMap();window.scrollTo({top:restoreY,behavior:'instant'});$('#page').focus({preventScroll:true});setupSegments();persist();}
function renderNav(){const nav=$('#bottomNav'),t=tripToday(new Date(),DATA.days,tripCalendarChanges),label=t.inTrip?'今日':t.boundary==='first'?'准备':'回顾';if(!nav.childElementCount)nav.innerHTML=[['home',label,'sun'],['itinerary','行程','calendar'],['map','地图','map'],['toolbox','工具','bag']].map(([v,n,i])=>`<button data-view="${v}">${outlineIco(i)}<span>${n}</span></button>`).join('');nav.querySelector('[data-view=home] span').textContent=label;nav.querySelectorAll('button').forEach(b=>{const active=b.dataset.view===state.view||(state.view==='day'&&b.dataset.view==='itinerary');b.classList.toggle('active',active);b.setAttribute('aria-current',active?'page':'false');});}
function renderRail(){const rail=$('#dayRail');if(state.view==='day'||document.body.dataset.view==='today')rail.innerHTML='<p class="editor-label">18 OCT — 04 NOV</p>'+DATA.days.map(d=>`<button data-day="${d.id}" class="calendar-tab ${d.id===state.day?'active':''}" ${d.id===state.day?'aria-current="date"':''}><strong>${shortDate(d.date)}</strong><small>${esc(d.title)}</small></button>`).join('');else rail.innerHTML='';}
function showDrawerFrame(frame){currentSheet=frame;$('#drawerBody').innerHTML=`<h1 id="drawerTitle">${esc(frame.title)}</h1>${frame.body}`;$('.drawer').scrollTop=frame.scroll||0;$('#closeDrawer').textContent=frame.parent?'← 返回上一级':'关闭 ×';$('#overlay').inert=false;$('#overlay').setAttribute('aria-hidden','false');$('#overlay').classList.add('open');['mainShell','bottomNav','topbar'].forEach(id=>$('#'+id).inert=true);document.body.style.overflow='hidden';updateClocks();const im=$('.detail-photo img');if(im){im.tabIndex=0;im.setAttribute('role','button');im.setAttribute('aria-label','全屏查看'+im.alt);}requestAnimationFrame(()=>{if(currentSheet===frame)$('#closeDrawer').focus({preventScroll:true});});animateContent($('#drawerBody'));}
function openDrawer(title,body){if(currentSheet)currentSheet.scroll=$('.drawer').scrollTop;const frame={id:++routeState.sheetId,title,body,parent:currentSheet,focus:document.activeElement,scroll:0};routeState.sheetFrames.set(frame.id,frame);if(!currentSheet){lastFocus=document.activeElement;saveScroll();}history.pushState({...history.state,sheet:frame.id},'',location.href);showDrawerFrame(frame);}
function hideDrawer(){if(!currentSheet)return;const focus=currentSheet.focus;currentSheet=null;$('#overlay').classList.remove('open');$('#overlay').setAttribute('aria-hidden','true');$('#overlay').inert=true;['mainShell','bottomNav','topbar'].forEach(id=>$('#'+id).inert=false);document.body.style.overflow='';if(focus?.isConnected)focus.focus({preventScroll:true});else lastFocus?.focus({preventScroll:true});}
