let lastPlanMinute='',lastHomePhase='';function refreshTime(){const now=new Date();updateClocks(now);const stamp=now.toISOString().slice(0,16);if(stamp===lastPlanMinute)return;lastPlanMinute=stamp;const t=tripToday(now,DATA.days,tripCalendarChanges);if(state.view==='home'){const phase=t.boundary+'-'+t.day+'-'+t.date;if(lastHomePhase&&phase!==lastHomePhase){render({restoreY:scrollY});}lastHomePhase=phase;}if(state.view==='day'||(state.view==='home'&&t.inTrip)){$('#planNow').innerHTML=timeCard(DATA.days[state.day-1],now);const pos=planPosition(DATA.days[state.day-1],now);$$('#planTimeline .timeline-row').forEach((row,i)=>{row.classList.toggle('is-current',i===pos.current);row.classList.toggle('is-next',i===pos.next);row.removeAttribute('aria-current');if(i===pos.current)row.setAttribute('aria-current','step');const badge=row.querySelector('.step-state');if(badge)badge.textContent=i===pos.current?'当前计划':i===pos.next?'下一项':'';});}renderNav();}
document.addEventListener('visibilitychange',()=>{if(!document.hidden){lastPlanMinute='';refreshTime();offlineRegistration?.update().catch(()=>{});}});window.addEventListener('pageshow',()=>{lastPlanMinute='';refreshTime();});setInterval(refreshTime,30000);
