let offlineRegistration=null;
function offlineBody(){let verified='尚未在此浏览器核验。';try{const saved=JSON.parse(localStorage.getItem('nordic-offline-verified')||'null');if(saved?.at)verified='上次核验：'+new Date(saved.at).toLocaleString('zh-CN')+'；版本 '+saved.version;}catch{}return `<p>离线关键资料包含每日安排、酒店、报到地点、航班、应急电话与清单。外部导航、天气道路查询需要联网，照片仅浏览后缓存。</p><p id="offlineStatus" role="status">${verified}</p><button class="primary-link" data-cache-prepare>准备并核验离线资料</button><div class="offline-links"><a href="essentials.html">精简资料页 · 可打印 / 保存 ↗</a><a href="offline.html" download="北境路书_2026_完整离线版.html">原完整离线版（约12MB） ↓</a><a href="compat.html">完整无脚本阅读版 ↗</a></div><p class="info-caption">微信可能限制下载或清除缓存。请在系统浏览器保存关键资料并断网重开同一网址，注册缓存服务不能代替验证。</p>`;}
async function prepareOffline(){const status=$('#offlineStatus');if(!navigator.serviceWorker){status.textContent='此浏览器不支持缓存，请保存精简资料页。';return;}status.textContent='正在准备并核验，请保持网络连接…';try{offlineRegistration=await navigator.serviceWorker.register(new URL('sw.js',document.baseURI));await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('缓存安装未完成，请联网后重试')),30000);navigator.serviceWorker.ready.then(r=>{clearTimeout(timer);resolve(r)},e=>{clearTimeout(timer);reject(e)});});const worker=offlineRegistration.active;if(!worker)throw Error('缓存服务尚未启动');const result=await new Promise((resolve,reject)=>{const channel=new MessageChannel(),timer=setTimeout(()=>reject(Error('准备超时，请联网后重试')),90000);channel.port1.onmessage=e=>{clearTimeout(timer);e.data.ok?resolve(e.data):reject(Error(e.data.error||'部分资源保存失败'));};worker.postMessage({type:'PREPARE'},[channel.port2]);});status.textContent=`已核验${result.count}项关键资源，版本 ${result.version}。请断网重开同一网址验证。`;try{localStorage.setItem('nordic-offline-verified',JSON.stringify({at:new Date().toISOString(),version:result.version}));}catch{}}catch(e){status.textContent='未完成离线准备：'+e.message+'。可保存精简资料页。';}}
function applyOfflineUpdate(){if(offlineRegistration?.waiting)offlineRegistration.waiting.postMessage({type:'ACTIVATE'});else location.reload();}
if(navigator.serviceWorker&&location.protocol!=='file:')navigator.serviceWorker.register(new URL('sw.js',document.baseURI)).then(r=>{offlineRegistration=r;const offer=()=>{if(r.waiting&&navigator.serviceWorker.controller&&!$('.update-banner')){const banner=document.createElement('aside');banner.className='update-banner';banner.innerHTML='路书有新版本 <button data-update>更新并重开</button>';document.body.append(banner);}};offer();r.addEventListener('updatefound',()=>r.installing?.addEventListener('statechange',offer));}).catch(()=>{});
let refreshing=false,wasControlled=!!navigator.serviceWorker?.controller;navigator.serviceWorker?.addEventListener('controllerchange',()=>{if(!wasControlled){wasControlled=true;return;}if(navigator.serviceWorker.controller&&!refreshing){refreshing=true;location.reload();}});
